def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    n = len(sites)
    p = s.get('element_properties') or {}
    occ = [max(a.get('occupancy', 1.0) or 0.0, 0.0) for a in sites]
    charges = []
    for site in sites:
        a = p.get(site.get('element')) or {}
        g = a.get('group')
        en = a.get('eneg')
        v = a.get('valence_electrons')
        row = a.get('row')
        q = 0.0
        if g == 1 or g == 2:
            q = float(g)
        elif g == 13:
            q = 3.0
        elif g == 14:
            q = -4.0 if en is not None and en >= 2.3 else 4.0
        elif g is not None and 15 <= g <= 17:
            q = float(g - 18)
        elif v is not None and ((g is not None and 3 <= g <= 12) or (g is None and row is not None and row >= 6)):
            q = min(max(v, 0.0), 3.0)
        charges.append(q)
    capacity = sum(occ[i] * abs(charges[i]) for i in range(n))
    if capacity <= 0:
        return 0.0
    neighbors = s.get('neighbors') or []
    nearest = [inf] * n
    for b in neighbors:
        i = b.get('i', -1)
        j = b.get('j', -1)
        d = b.get('distance_A') or 0.0
        if 0 <= i < n and 0 <= j < n and d > 1e-8 and occ[j] > 0:
            nearest[i] = min(nearest[i], d)
    degree = [0.0] * n
    for b in neighbors:
        i = b.get('i', -1)
        j = b.get('j', -1)
        d = b.get('distance_A') or 0.0
        if 0 <= i < n and 0 <= j < n and d > 1e-8 and d <= 1.25 * max(nearest[i], nearest[j]):
            if charges[i] * charges[j] < 0:
                degree[i] += occ[j]
    transfer = 0.0
    for b in neighbors:
        i = b.get('i', -1)
        j = b.get('j', -1)
        d = b.get('distance_A') or 0.0
        if 0 <= i < n and 0 <= j < n and d > 1e-8 and d <= 1.25 * max(nearest[i], nearest[j]):
            if charges[i] > 0 and charges[j] < 0 and degree[i] > 0 and degree[j] > 0:
                transfer += occ[i] * occ[j] * min(charges[i] / degree[i], -charges[j] / degree[j])
    return max(0.0, min(1.0, 1.0 - 2.0 * transfer / capacity))

