        a = p.get(site.get('element')) or {}
        g = a.get('group')
        en = a.get('eneg')
        v = a.get('valence_electrons')
        row = a.get('row')
        donor = g == 1 or g == 2 or g == 13
        if g == 14:
            donor = en is None or en < 2.3
        elif v is not None and v > 0 and ((g is not None and 3 <= g <= 12) or (g is None and row is not None and row >= 6)):
            donor = True
        donors.append(donor)
    neighbors = s.get('neighbors') or []
    nearest = [inf] * n
    for b in neighbors:
        i = b.get('i', -1)
        j = b.get('j', -1)
        d = b.get('distance_A') or 0.0
        if 0 <= i < n and 0 <= j < n and d > 1e-8 and occ[j] > 0:
            nearest[i] = min(nearest[i], d)
    total = 0.0
    weight = 0.0
    for b in neighbors:
        i = b.get('i', -1)
        j = b.get('j', -1)
        d = b.get('distance_A') or 0.0
        if 0 <= i < n and 0 <= j < n and d > 1e-8 and d <= 1.25 * nearest[i]:
            w = occ[i] * occ[j]
            weight += w
            if donors[i] and donors[j]:
                total += w
    return total / weight if weight > 0 else 0.0
